begin;
create temp table _had_note on commit drop as select id from public.areas where parking_note is not null;
update public.areas set parking_note='Park in the lot just over the bridge on NY Route 167 in Little Falls: take the first drive on the right after crossing the river and park right under the bridge.' where id='ny_moss_island_climbs' and id not in (select id from _had_note);
update public.areas set parking_note='Park in the lot just over the bridge on NY Route 167 in Little Falls: take the first drive on the right after crossing the river and park right under the bridge.' where path <@ (select path from public.areas where id='ny_moss_island_climbs') and id <> 'ny_moss_island_climbs' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Park on the east side of the road at the large dirt turn-out at County Road 104 and Utah 211, then go through the ranch gate (close it) and follow a trail northeast, almost 2 miles. A capable 2WD may drive closer; conditions may have changed.' where id='ut_cat_wall' and id not in (select id from _had_note);
update public.areas set parking_note='Park on the east side of the road at the large dirt turn-out at County Road 104 and Utah 211, then go through the ranch gate (close it) and follow a trail northeast, almost 2 miles. A capable 2WD may drive closer; conditions may have changed.' where path <@ (select path from public.areas where id='ut_cat_wall') and id <> 'ut_cat_wall' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Turn onto Whippoorwill Road just off US-19 near the bridge, follow it right and downhill, and park at the pullout on the more obvious second dirt road on the left. If full, park fully off the road; do not use the gravesite parking.' where id='wv_whippoorwill' and id not in (select id from _had_note);
update public.areas set parking_note='Turn onto Whippoorwill Road just off US-19 near the bridge, follow it right and downhill, and park at the pullout on the more obvious second dirt road on the left. If full, park fully off the road; do not use the gravesite parking.' where path <@ (select path from public.areas where id='wv_whippoorwill') and id <> 'wv_whippoorwill' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Park at the Seneca Rocks visitor center lots (upper or lower; lower is closer) just south on US 33, then hike up Roy Gap Road to the creek crossing with the stone stairs on the far side, which leads up to the West Face.' where id='wv_south_peak_west_face_main_area' and id not in (select id from _had_note);
update public.areas set parking_note='Park at the Seneca Rocks visitor center lots (upper or lower; lower is closer) just south on US 33, then hike up Roy Gap Road to the creek crossing with the stone stairs on the far side, which leads up to the West Face.' where path <@ (select path from public.areas where id='wv_south_peak_west_face_main_area') and id <> 'wv_south_peak_west_face_main_area' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Park at the intersection of Reeds Creek Road with Route 220 near Upper Tract, or in one of two small pull-outs on the left of Reeds Creek Road (about 100 ft and 500 ft in, 2-3 cars each). Parking is limited and can fill; do not park outside the obvious spots.' where id='wv_reeds_creek' and id not in (select id from _had_note);
update public.areas set parking_note='Park at the intersection of Reeds Creek Road with Route 220 near Upper Tract, or in one of two small pull-outs on the left of Reeds Creek Road (about 100 ft and 500 ft in, 2-3 cars each). Parking is limited and can fill; do not park outside the obvious spots.' where path <@ (select path from public.areas where id='wv_reeds_creek') and id <> 'wv_reeds_creek' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Drive from Cashiers via US 64, Cedar Creek Road and Breedlove Road to the Panthertown Valley trailhead lot at Salt Rock Gap, where the gravel road ends. This trailhead is the only legal access; do not approach from Dillard Canyon (private).' where id='nc_laurel_knob' and id not in (select id from _had_note);
update public.areas set parking_note='Drive from Cashiers via US 64, Cedar Creek Road and Breedlove Road to the Panthertown Valley trailhead lot at Salt Rock Gap, where the gravel road ends. This trailhead is the only legal access; do not approach from Dillard Canyon (private).' where path <@ (select path from public.areas where id='nc_laurel_knob') and id <> 'nc_laurel_knob' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='The crag is on South 5th Ave in Pocatello, below the Fort Hall Replica and Upper Ross Park. Park at the north or south end of the park; the road is busy, so watch kids and dogs.' where id='id_shady_side' and id not in (select id from _had_note);
update public.areas set parking_note='The crag is on South 5th Ave in Pocatello, below the Fort Hall Replica and Upper Ross Park. Park at the north or south end of the park; the road is busy, so watch kids and dogs.' where path <@ (select path from public.areas where id='id_shady_side') and id <> 'id_shady_side' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='The Overlook is on the east side of Highway 89A at the top of Oak Creek Canyon, just before the switchbacks. Use the paved lot, but if staying past 4:30 pm park across the highway because the gates are locked then.' where id='az_overlook_the' and id not in (select id from _had_note);
