update public.areas set parking_note='Flatrock, about 20 minutes north of St. John''s: park in the East Coast Trail lot just past the public wharf. Parking on Wade''s Lane is no longer permitted, so use the designated lots only.' where id='nl_main_face' and id not in (select id from _had_note);
