update public.areas set parking_note='Hospital Boulders: park in the gated lot on the climber-owned property off Scenic Highway in Gadsden, then walk past the barn on the narrow entry road to a trail trending downhill. The property is open dawn to dusk only; the gate combination is shared by the local climbing group.' where id='al_barn_area' and id not in (select id from _had_note);
update public.areas set parking_note='Hospital Boulders: park in the gated lot on the climber-owned property off Scenic Highway in Gadsden, then walk past the barn on the narrow entry road to a trail trending downhill. The property is open dawn to dusk only; the gate combination is shared by the local climbing group.' where path <@ (select path from public.areas where id='al_barn_area') and id <> 'al_barn_area' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Hospital Boulders: park in the gated lot on the climber-owned property off Scenic Highway in Gadsden, then walk past the barn and follow the trail downhill and right. The property is open dawn to dusk only; the gate combination is shared by the local climbing group.' where id='al_eddie_area' and id not in (select id from _had_note);
